INSERT INTO visits (id, patient_id, date, dr_stage, confidence, heatmap_regions, notes, image_quality, image_url, eye, analysis) VALUES ('vGV-007-0','GV-007','2026-05-10',1,0.92,'[{"x": 35, "y": 46, "r": 17, "label": "exudates"}]','Mild NPDR, microaneurysms',88,'/images/fundus-mild.jpg','left','{"summary": "Mild NPDR \u2014 1 exudates at 88/100 quality, 92% confidence. Risk 95/100.", "lesionsDetected": [{"type": "exudates", "count": 1, "locations": "inferonasal (35%,46%)", "severity": "mild"}], "stageJustification": "1\u20133 microaneurysms in posterior pole (heatmap 35%/46% if present). No haemorrhage or exudate beyond. Single lesion cluster = Mild NPDR (ETDRS 20-35).", "confidenceExplanation": "High confidence (92%) because image quality 88/100 is sharp, lesions are conspicuous with distinct borders, and model agreement across 5 folds >0.90. Heatmap intensity peaks >0.85 over lesions, no artefacts.", "riskScoreBreakdown": [{"factor": "HbA1c", "value": "8.7%", "contribution": "moderate \u2014 chronic hyperglycemia drives microvascular damage; HbA1c 8.7% is above target <7%"}, {"factor": "Blood pressure", "value": "159/90", "contribution": "high \u2014 HTN accelerates DR; systolic 159 mmHg elevated"}, {"factor": "Diabetes duration", "value": "18y", "contribution": "high \u2014 longer duration increases cumulative exposure; 18y Type 2"}, {"factor": "Family history", "value": "No", "contribution": "No familial clustering"}, {"factor": "Symptoms", "value": "floaters", "contribution": "Symptomatic (blur/floaters) correlates with macular involvement"}], "imageQualityAssessment": "Good 88/100 \u2014 adequate focus, slight under-illumination at temporal periphery but lesions remain gradable. No blur gate block.", "clinicalSignificance": "Mild NPDR is earliest visible DR \u2014 microaneurysms only, no macular threat. Indicates end-organ damage has begun; systemic control must tighten to prevent progression to moderate.", "recommendedActions": ["Re-screen 6m, tighten glycemic control", "BP/lipid optimization, smoking cessation", "Patient education: report floaters/flashes immediately"], "urgency": "routine", "dietPlan": {"summary": "Tighten control to stop mild changes from growing.", "dos": ["Millet + dal + green veg", "1 fruit and almonds", "Salt <5g, BP check", "Walk 30-45 min"], "donts": ["No added sugar or sweet drinks", "Limit salt and packaged snacks", "No tobacco"], "dailyCalories": "1400-1500 kcal", "followUp": "Eye check in 6 months"}}');
